"""Explicit review of twenty pending units; not a full CPP certification."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,CP,LEP,*links])
add('474-a','Na instrução do plenário, participantes devem respeitar dignidade da vítima; presidente garante proteção.', ['Lei14.245/2021.', 'Vedados elementos alheios aos fatos e linguagem, informação ou material ofensivos à vítima ou testemunhas.'], 'Defesa pode questionar prova pertinente, mas não humilhar pessoa por aspectos estranhos ao fato.', 'Parte tenta exibir material íntimo sem relação com apuração; presidente impede a ofensa.', 'Contradição pertinente é perguntada de modo respeitoso, sem suprimir defesa legítima.', ['Regra protege também testemunhas contra linguagem ofensiva? Sim.', 'Veda qualquer pergunta pertinente da defesa? Não.'], 'Dignidade em plenário','Proteção pessoal compatível com produção legítima de prova.',['https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14245.htm'])
add(761,'Competência e reunião de títulos seguem organização atual e LEP; remissão ao antigo CP84§2 não basta.', ['CP84 atual trata soma para livramento.', 'Conferir competência e incidente cabível.'], 'Não escolher juiz somente pelo último julgamento com base em remissão materialmente antiga.', 'Execução recebe títulos e examina competência atual para providência pertinente.', 'Duas sentenças não autorizam restaurar cumulação histórica de medidas.', ['Número antigo identifica sempre conteúdo atual? Não.', 'Competência exige regras atuais? Sim.'], 'Remissão executória','Referência sujeita à correspondência atual.')
add(762,'Guia de medida válida identifica pessoa, título e parâmetros, integrada à LEP171–173.', ['Não internar sem guia judicial pertinente.', 'Prazo mínimo não equivale a liberação automática nem autoriza custódia perpétua.'], 'Documento não supre pressupostos materiais ou cuidado em saúde adequado.', 'Medida legalmente imposta é encaminhada com identificação e decisão.', 'Erro no título precisa ser corrigido, sem inventar internação pela guia.', ['Guia cria medida sem decisão válida? Não.', 'Prazo mínimo é limite máximo automático? Não.'], 'Guia da medida','Documento de execução do título de segurança.')
add(763,'Cumprimento de ordem referente a medida depende de título válido e garantias atuais.', ['Oficial ou polícia cumpre ordem judicial.', 'Integrar tratamento e execução legal.'], 'Não capturar pessoa só por diagnóstico ou por mandato informal da direção.', 'Ordem válida é cumprida com identificação correta e proteção da integridade.', 'Pessoa com mesmo nome exige conferência, não captura por mera semelhança.', ['Diagnóstico sozinho autoriza captura penal? Não.', 'Identidade deve ser conferida? Sim.'], 'Cumprimento da ordem','Efetivação legal do título de medida.')
add(764,'Trabalho do internado precisa considerar capacidade, finalidade educativa e remuneração no regime atual.', ['Remissão a estabelecimentos do CP antigo exige integração.', 'Saúde limita atividade compatível.'], 'Não impor trabalho incompatível com condição clínica nem reproduzir instituição antiga como única forma de cuidado.', 'Atividade compatível é organizada com acompanhamento e remuneração legal.', 'Inaptidão demonstrada exige adaptação, não punição automática por falta de trabalho.', ['Condições pessoais importam? Sim.', 'Trabalho pode ser imposto sem considerar saúde? Não.'], 'Atividade compatível','Trabalho adequado à pessoa e ao regime legal.')
add(765,'Distribuição antiga do salário não deve substituir destinações e proteção atuais da LEP29.', ['Não aplicar retirada fixa universal de um quarto.', 'Distinguir remuneração e pecúlio.'], 'O texto histórico não autoriza Estado a apropriar parcela automaticamente sem regime atual.', 'Remuneração é destinada conforme obrigações e limites legais pertinentes.', 'Recursos da família não são calculados só por três quartos históricos.', ['Estado recebe automaticamente25% em todo caso atual? Não.', 'Pecúlio e destinações exigem regime legal? Sim.'], 'Destinação remuneratória','Distribuição do produto do trabalho conforme lei vigente.')
add(766,'Proteção das mulheres exige acomodação e cuidado adequados no regime atual, sem internação automática por sexo.', ['Separação e integridade devem ser garantidas.', 'Integrar saúde e direitos não atingidos pelo título.'], 'Seção própria não dispensa cuidado clínico nem valida instituição inadequada.', 'Pessoa recebe atendimento com segurança e proteção da intimidade.', 'Necessidade clínica é individualizada; ser mulher não cria título de medida.', ['Separação dispensa assistência à saúde? Não.', 'Sexo cria medida penal por si? Não.'], 'Proteção da internada','Garantias de integridade e cuidado adequado.')
add(767,'Liberdade vigiada do sistema antigo não é espécie atual automática de medida de segurança.', ['CP96 prevê espécies atuais.', 'Não confundir com sursis, livramento ou cautelar.'], 'Obrigações antigas não podem ser importadas integralmente sem título atual e base legal.', 'Condição de livramento é examinada pela LEP132, não por medida histórica genérica.', 'Proibir locais exige hipótese atual cabível, não simples menção à liberdade vigiada.', ['Liberdade vigiada antiga é medida atual universal? Não.', 'Livramento tem condições próprias? Sim.'], 'Liberdade vigiada histórica','Modelo antigo distinto dos institutos atuais.')
add(768,'Comunicação de obrigações deve derivar de decisão válida; remissão à vigilância antiga exige integração.', ['Identificar destinatário e finalidade legais.', 'Não criar restrições pela comunicação.'], 'Ofício à polícia não valida obrigação incompatível com regime atual.', 'Condições legalmente fixadas são informadas ao órgão pertinente.', 'Polícia não acrescenta horário proibido por vontade própria.', ['Comunicação cria novas restrições? Não.', 'Obrigação precisa de base válida? Sim.'], 'Ciência institucional','Informação para cumprir decisão legal.')
add(769,'Acompanhamento legítimo deve preservar pessoa e não produzir exposição ou prejuízo arbitrário.', ['Discrição do texto não restaura espécie antiga.', 'Integrar finalidade e competência atuais.'], 'Vigilância discreta não autoriza monitoramento sem base legal.', 'Órgão competente acompanha condição válida sem divulgação humilhante.', 'Avisar empregador indiscriminadamente exige fundamento, não mera conveniência.', ['Discrição dispensa base legal? Não.', 'Exposição arbitrária é autorizada? Não.'], 'Acompanhamento discreto','Atuação legal que evita prejuízo indevido.')
add(770,'Alteração de condições depende de competência, título e instituto atuais, sem recuperar liberdade vigiada histórica.', ['Decisão deve ser comunicada.', 'Não punir obrigação retroativa inexistente.'], 'Pedido policial não torna válida qualquer condição sugerida.', 'Condição de benefício atual é ajustada motivadamente pelo juiz competente.', 'Regra nova sem ciência não prova descumprimento anterior.', ['Pedido policial impõe condição sozinho? Não.', 'Alteração exige decisão legal? Sim.'], 'Ajuste de condições','Mudança jurisdicional sob limites atuais.')
add(771,'Exílio local é medida histórica que não integra automaticamente espécies atuais do CP96.', ['Não confundir cautelar de proibição de acesso com banimento.', 'Liberdade não pode ser limitada sem hipótese atual.'], 'Não ensinar expulsão geográfica ou detenção pelo exílio antigo como regra vigente.', 'Juízo examina cautelar atual cabível com fundamento próprio.', 'Morador não é banido de cidade por mera aplicação do dispositivo histórico.', ['Exílio local é medida atual genérica? Não.', 'Cautelar exige base distinta? Sim.'], 'Exílio histórico','Instituto antigo que não equivale às cautelares atuais.')
add(772,'Proibição de locais precisa de base atual, não de aplicação automática do modelo histórico de medida.', ['Distinguir cautelar, pena restritiva e condição de benefício.', 'Comunicação não substitui título.'], 'Mesmo nome de obrigação não iguala institutos nem consequências de descumprimento.', 'Cautelar de acesso é comunicada sob decisão fundamentada do regime pertinente.', 'Descumprimento de condição de livramento segue seu procedimento, não sanção antiga automática.', ['Nome semelhante torna regimes idênticos? Não.', 'Título determina consequências? Sim.'], 'Proibição delimitada','Restrição fundada no instituto legal adequado.')
add(773,'Fechamento ou interdição exige hipótese atual própria e decisão competente, não medida histórica universal.', ['Não restaurar espécies antigas pelo CP96.', 'Separar sanção penal, cautelar e atuação administrativa.'], 'Comunicar à polícia não basta para fechar qualquer entidade por suspeita.', 'Hipótese específica legalmente cabível é apreciada com garantias pertinentes.', 'Associação lícita não é interditada só por relatório vago de perigo.', ['Relatório vago basta para interdição penal? Não.', 'Hipótese legal específica precisa existir? Sim.'], 'Interdição específica','Providência dependente de competência e fundamento atuais.')
add(774,'Transgressão de medida não autoriza impor outra automaticamente pela remissão histórica ao CP83.', ['CP83 atual trata livramento.', 'Identificar medida, incidente e regime vigentes.'], 'Não trocar conteúdo do artigo atual por número antigo nem dispensar defesa.', 'Incidente de medida válida é apurado conforme CP e LEP pertinentes.', 'Falta de comparecimento não cria por si espécie de medida histórica adicional.', ['CP83 atual corresponde integralmente à remissão antiga? Não.', 'Transgressão permite medida extra arbitrária? Não.'], 'Incidente da medida','Apuração no regime legal atual.')
add(775,'Reavaliação da medida segue CP97 e LEP175: relatório, laudo e participação antes de decisão.', ['Não recuperar exílio ou liberdade vigiada.', 'Distinguir laudo clínico e decisão judicial.', 'Prazos e garantias devem seguir regime atual.'], 'Não manter custódia indefinidamente por demora de relatório ou confundir prazo mínimo com sentença de prisão perpétua.', 'Relatório e laudo instruem análise judicial com manifestações pertinentes.', 'Fim do prazo mínimo exige exame, não automática continuidade sem controle.', ['Laudo substitui decisão judicial? Não.', 'Prazo mínimo dispensa reavaliação? Não.'], 'Reavaliação da medida','Controle periódico dos pressupostos e cuidado.')
add(776,'Exames sucessivos devem integrar CP97§2 e LEP177, não remissões do CP81 antigo.', ['CP81 atual trata sursis.', 'Aplicar procedimento compatível de reavaliação.'], 'Não misturar revogação do sursis com perícia de medida apenas por número de artigo.', 'Juízo determina reavaliação no regime próprio da medida.', 'Novo relatório não elimina participação defensiva cabível.', ['CP81 atual tem objeto histórico referido? Não.', 'Exames seguem regime vigente? Sim.'], 'Exame sucessivo','Reavaliação posterior com procedimento legal.')
add(777,'Reavaliação pode ser determinada antes do prazo mínimo quando cabível, integrada à LEP176 e CP97.', ['Pedido fundamentado e competência atuais.', 'Antecipar exame não garante liberação automática.'], 'Não obrigar pessoa a esperar todo prazo mínimo para qualquer avaliação legalmente antecipável.', 'Dados clínicos novos fundamentam pedido de exame antecipado.', 'Exame solicitado não concede desinternação sem análise dos pressupostos.', ['É sempre proibido exame antes do prazo mínimo? Não.', 'Pedido equivale a liberação imediata? Não.'], 'Exame antecipado','Reavaliação cabível antes do marco mínimo.')
add(778,'Decisão deve ser efetivada por ordem adequada de desinternação ou liberação, integrada à LEP178–179 e CP97.', ['Distinguir cessação e período condicional.', 'Não restaurar vigilância histórica como espécie atual.'], 'Liberação condicional da medida não é igual a livramento da pena; outra causa válida precisa ser conferida.', 'Decisão de desinternação é comunicada para efetivação e cuidado pertinente.', 'Condições atuais são examinadas sem reativar exílio antigo.', ['Desinternação equivale a livramento da pena? Não.', 'Decisão exige implementação? Sim.'], 'Desinternação','Saída do regime detentivo sob pressupostos atuais.')
add(779,'Confisco deve ser integrado ao CP91 e regras atuais sobre bens, não à remissão ao antigo CP100.', ['Proteger lesado e terceiro de boa-fé.', 'Identificar natureza do bem e base de perdimento.', 'Arquivamento ou absolvição não produzem todo confisco automaticamente.'], 'Não confiscar qualquer patrimônio lícito por simples despacho de arquivamento.', 'Objeto de posse ilícita exige exame da providência legal cabível.', 'Bem lícito de terceiro de boa-fé reclama proteção e análise de restituição, não perda genérica.', ['Todo arquivamento confisca qualquer bem? Não.', 'Terceiro de boa-fé exige proteção? Sim.'], 'Perdimento delimitado','Consequência patrimonial sujeita à base legal atual.')
